package com.bank.queryopt.storage;

import com.bank.queryopt.model.Txn;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.*;
import java.util.logging.Logger;

// Monthly partitions → a date-ranged query prunes to one partition.
public class PartitionedTable {
    private static final Logger log = Logger.getLogger(PartitionedTable.class.getName());
    private final Map<YearMonth, List<Txn>> partitions = new TreeMap<>();

    public void insert(Txn t) {
        partitions.computeIfAbsent(YearMonth.from(t.getDate()), k -> new ArrayList<>()).add(t);
    }

    // Full scan (the slow baseline).
    public BigDecimal fullScanTotal(String accountId) {
            long scanned = 0;
            BigDecimal total = BigDecimal.ZERO;
        for (List<Txn> part : partitions.values())
            for (Txn t : part) { scanned++; if (t.getAccountId().equals(accountId)) total = total.add(t.getAmount()); }
        log.warning("FULL SCAN rows scanned = " + scanned);
        return total;
    }

    // Pruned scan: only the partition matching the month.
    public BigDecimal prunedTotal(String accountId, YearMonth month) {
            long scanned = 0;
            BigDecimal total = BigDecimal.ZERO;
        List<Txn> part = partitions.getOrDefault(month, List.of());
        for (Txn t : part) { scanned++; if (t.getAccountId().equals(accountId)) total = total.add(t.getAmount()); }
        log.info("PARTITION PRUNED to " + month + ", rows scanned = " + scanned);
        return total;
    }
    public long totalRows() { return partitions.values().stream().mapToLong(List::size).sum(); }
}
