package com.bank.queryopt.storage;

import com.bank.queryopt.model.Txn;
import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.*;
import java.util.logging.Logger;

// Covering index: (account_id, month) → amounts, so the query is index-only.
public class CoveringIndex {
    private static final Logger log = Logger.getLogger(CoveringIndex.class.getName());
    private final Map<String, List<BigDecimal>> index = new HashMap<>();

    public void build(List<Txn> txns) {
        for (Txn t : txns) {
            String key = t.getAccountId() + "|" + YearMonth.from(t.getDate());
            index.computeIfAbsent(key, k -> new ArrayList<>()).add(t.getAmount());
        }
    }

    public BigDecimal indexOnlyTotal(String accountId, YearMonth month) {
        List<BigDecimal> amounts = index.getOrDefault(accountId + "|" + month, List.of());
        BigDecimal total = BigDecimal.ZERO;
        for (BigDecimal a : amounts) total = total.add(a);
        log.info("INDEX-ONLY scan, entries read = " + amounts.size() + " (no heap lookup)");
        return total;
    }
}
