package com.bank.queryopt.storage;

import com.bank.queryopt.model.Txn;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import java.util.logging.Logger;

// Pre-aggregated daily per-account totals for repeated rollups.
public class MaterializedView {
    private static final Logger log = Logger.getLogger(MaterializedView.class.getName());
    private final Map<String, BigDecimal> rollup = new LinkedHashMap<>();

    public void refresh(List<Txn> txns) {
        rollup.clear();
        for (Txn t : txns) rollup.merge(t.getDate() + "|" + t.getAccountId(), t.getAmount(), BigDecimal::add);
        log.info("MATERIALIZED VIEW refreshed: " + rollup.size() + " pre-aggregated rows");
    }

    public BigDecimal read(LocalDate date, String accountId) {
        BigDecimal v = rollup.getOrDefault(date + "|" + accountId, BigDecimal.ZERO);
        log.info("MV read (1 row, no fact scan) = " + v);
        return v;
    }
}
