package com.bank.queryopt;

import com.bank.queryopt.model.Txn;
import com.bank.queryopt.storage.*;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.*;
import java.util.logging.Logger;

public class QueryOptDemo {
    private static final Logger log = Logger.getLogger(QueryOptDemo.class.getName());

    public static void main(String[] args) {
        // Build a small stand-in for a huge table: 3 months of data.
        List<Txn> all = new ArrayList<>();
        long id = 1;
        for (int m = 8; m <= 10; m++)
            for (int d = 1; d <= 4; d++)
                all.add(new Txn(id++, (d % 2 == 0 ? "SAV2001" : "CUR3001"),
                        LocalDate.of(2024, m, d), new BigDecimal("1000")));

        PartitionedTable table = new PartitionedTable();
        all.forEach(table::insert);
        log.info("Table rows = " + table.totalRows());

        log.info("=== Baseline: full scan ===");
        table.fullScanTotal("SAV2001");

        log.info("=== Optimization 1: partition pruning ===");
        table.prunedTotal("SAV2001", YearMonth.of(2024, 10));

        log.info("=== Optimization 2: covering index (index-only) ===");
        CoveringIndex idx = new CoveringIndex();
        idx.build(all);
        idx.indexOnlyTotal("SAV2001", YearMonth.of(2024, 10));

        log.info("=== Optimization 3: materialized view ===");
        MaterializedView mv = new MaterializedView();
        mv.refresh(all);
        mv.read(LocalDate.of(2024, 10, 2), "SAV2001");
    }
}
